mapper.select:
select tm.user_id as userId ,tm.medicine_id as medicineId ,tm.medicine_name as medicineName ,tm.manufacturer as manufacturer ,tm.production_date as productionDate ,tm.shelf_life_months as shelfLifeMonths ,tm.expiry_date as expiryDate ,tm.remaining_quantity as remainingQuantity ,tm.tablets_per_box as tabletsPerBox ,tm.intake_time_code as intakeTimeCode ,tcm.code_name as intakeTimeCodeName ,tm.daily_times as dailyTimes ,tm.tablets_per_time as tabletsPerTime ,tm.tablets_Count_All as tabletsCountAll ,tm.remark as remark from t_medicine tm left join t_code_mst tcm on tcm.code_type_id = '001' and tcm.code_id = tm.intake_time_code where tm.user_id = #{userId}
AND medicine_name LIKE CONCAT('%', #{medicineName}, '%')
ORDER BY medicine_id DESC
